import {reviewsMarkup} from './store-site-reviews.js';
import {withSiteLayout} from './site-layout.js';
import {styleSiteText} from './site-text-style.js';
import {readCollections} from './equipment-site-collections.js';
import {defaultLabSite,mergeLabSite} from './lab-site-content.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const EQUIPMENT_IMAGES={logo:'/equipment-site/logo.svg',hero:'/equipment-site/studio-camera.webp',print:'/equipment-site/studio-camera.webp',paper:'/equipment-site/equipment-kit.webp',gallery:'/equipment-site/equipment-kit.webp'};
export function defaultEquipmentSite(shop){return {...defaultLabSite(shop),displayName:String(shop.name||'فروشگاه').slice(0,120),tagline:'',heroTitle:'ابزار درست،\nبرای تصویر بعدی شما.',heroText:'تجهیزات عکاسی و فیلم‌برداری را با توجه به نیاز پروژه انتخاب کنید. کالاهای فعال، قیمت فروش و مسیر آفیش تجهیزات را در همین فروشگاه ببینید.',heroButton:shop.sale_enabled===false?'مشاهدهٔ تجهیزات اجاره':'مشاهدهٔ محصولات',secondaryButton:'راهنمای انتخاب تجهیزات',heroNote:'فروش عمومی و همکاری عکاسان، هرکدام با مسیر مشخص',stampText:'آماده برای ایدهٔ بعدی',ribbon1:'مشاهدهٔ کالاهای فعال',ribbon2:'راهنمای انتخاب تجهیزات',ribbon3:'آفیش با حساب عکاس',
 servicesTitle:'انتخاب تجهیزات، با شناخت بیشتر',servicesText:'از دوربین و لنز تا لوازم پروژه؛ پیش از سفارش، نیاز و سازگاری تجهیزات را بررسی کنید.',printTitle:'خرید تجهیزات عکاسی',printText:'کالاهای منتشرشدهٔ فروشگاه را ببینید و مشخصات، قیمت و موجودی آن‌ها را مقایسه کنید.',printButton:'مشاهدهٔ کالاها',paperTitle:'تجهیز پروژهٔ عکاسی و فیلم‌برداری',paperText:'نوع پروژه، بدنه، لنز و لوازم جانبی را کنار هم بسنجید؛ سازگاری هر قطعه اهمیت دارد.',paperButton:'راهنمای انتخاب',proTitle:shop.rental_enabled?'آفیش تجهیزات برای عکاسان':'راهنمای سفارش و تحویل',proText:shop.rental_enabled?'عکاس با حساب خود وارد می‌شود و پس از تأیید همکاری، درخواست آفیش تجهیزات می‌دهد.':'مشخصات سفارش، روش پرداخت و شرایط تحویل را پیش از خرید با فروشگاه هماهنگ کنید.',proButton:shop.rental_enabled?'مسیر آفیش تجهیزات':'راهنمای سفارش',
 stepsTitle:'از نیاز پروژه تا ثبت درخواست',step1Title:'نیاز پروژه را مشخص کنید',step1Text:'نوع عکاسی یا فیلم‌برداری، نور محیط و مدت استفاده را مشخص کنید.',step2Title:'مشخصات و سازگاری را بررسی کنید',step2Text:'مدل، مانت لنز، اتصالات، متعلقات و شرایط استفاده را پیش از انتخاب بررسی کنید.',step3Title:'در مسیر مناسب سفارش دهید',step3Text:'برای خرید، سبد عمومی را تکمیل کنید. برای اجاره، از حساب عکاس و مسیر آفیش استفاده کنید.',stepsButton:'راهنمای خرید و آفیش',galleryTitle:'یک انتخاب هماهنگ برای پروژه',galleryText:'انتخاب هماهنگ دوربین، لنز و لوازم جانبی برای پروژهٔ عکاسی و فیلم‌برداری.',galleryCaption:'',galleryButton:'راهنمای انتخاب لنز',
 guideTitle:'قبل از انتخاب، بخوانید',guideText:'راهنماهایی برای شناخت دوربین، سازگاری لنز و برنامه‌ریزی اجارهٔ تجهیزات.',guide1Title:'دوربین را متناسب با کار انتخاب کنید',guide1Text:'کاربرد، نیاز ویدئویی و لوازم همراه را با هم بررسی کنید.',guide2Title:'لنز مناسب، با مانت درست',guide2Text:'مانت، اندازهٔ حسگر و فاصلهٔ کانونی را پیش از خرید یا اجاره بشناسید.',guide3Title:'برای آفیش تجهیزات آماده شوید',guide3Text:'تاریخ‌ها، متعلقات و شرایط تحویل را پیش از ثبت درخواست مشخص کنید.',
 faq1Q:'برای خرید تجهیزات باید عکاس همکار باشم؟',faq1A:'خرید عمومی کالاهای فعال فروشگاه از مسیر سبد خرید انجام می‌شود و با آفیش تجهیزات متفاوت است. امکان فروش به تنظیمات فروشگاه و موجودی کالا وابسته است.',faq2Q:'چطور تجهیزات را اجاره کنم؟',faq2A:'اگر اجاره در فروشگاه فعال باشد، از بخش آفیش با حساب عکاسی خود وارد شوید. دسترسی و ثبت درخواست به تأیید همکاری، تاریخ‌ها و موجودی همان فروشگاه وابسته است.',faq3Q:'قیمت و موجودی را کجا ببینم؟',faq3A:'قیمت فروش عمومی در کارت کالاها نمایش داده می‌شود. تعرفهٔ اجاره و دسترسی عکاس در مسیر آفیش و مطابق شرایط همکاری همان فروشگاه بررسی می‌شود.',
 aboutTitle:'آشنایی با فروشگاه ما',aboutText:shop.description?String(shop.description).slice(0,1400):'این سایت، مسیر مستقیم ارتباط با '+shop.name+' برای مشاهدهٔ تجهیزات و ثبت درخواست است. فروش عمومی و آفیش عکاسان، مطابق خدمات فعال فروشگاه ارائه می‌شوند.',contactTitle:'برای انتخاب بهتر، هماهنگ کنیم',contactText:'برای بررسی سازگاری، متعلقات، شرایط فروش یا هماهنگی تحویل تجهیزات با فروشگاه تماس بگیرید. اگر سفارش ثبت کرده‌اید، شمارهٔ آن را آماده داشته باشید.',phone:String(shop.phone||'').slice(0,40),address:String(shop.address||'').slice(0,500),navPhotographers:shop.rental_enabled?'ورود عکاسان':'مشاهدهٔ فروشگاه',navServices:'خدمات تجهیزات',navPrices:'محصولات',navGuides:'راهنمای تجهیزات',footerText:'ابزار تصویر، متناسب با ایدهٔ شما.',images:{...EQUIPMENT_IMAGES}};}
export function mergeEquipmentSite(shop,saved){const c=mergeLabSite(shop,saved,defaultEquipmentSite(shop));if(c.galleryText==='چیدمان نمایشی برای الهام در انتخاب تجهیزات؛ کالاهای قابل سفارش را در فهرست واقعی فروشگاه ببینید.')c.galleryText=defaultEquipmentSite(shop).galleryText;return readCollections(c,saved,shop);}
const field=(c,key,tag='span',attrs='')=>`<${tag} data-site-field="${key}" ${attrs}>${esc(c[key])}</${tag}>`;
const img=(c,key,alt)=>`<img data-site-image="${key}" src="${esc(c.images[key])}" width="1200" height="800" alt="${esc(alt)}" ${key==='hero'?'fetchpriority="high"':'loading="lazy"'}>`;
const arrow='';
const localPath=shop=>shop.city?'/equipment/'+(shop.city==='کرج'?'karaj':'city/'+encodeURIComponent(shop.city)):null;
export function equipmentPages(shop){return [['/','فروشگاه تجهیزات عکاسی'],['/products','محصولات فروشگاه'],['/equipment','تجهیزات عکاسی و فیلم‌برداری'],...(shop.rental_enabled?[['/rental-equipment','اجاره و آفیش تجهیزات']]:[]),['/guides','راهنمای تجهیزات'],['/guides/camera','راهنمای انتخاب دوربین'],['/guides/lenses','راهنمای انتخاب لنز'],['/guides/rental','راهنمای آفیش تجهیزات'],['/order-guide','راهنمای خرید و آفیش'],['/faq','پرسش‌های متداول'],['/reviews','نظر کاربران'],['/about','دربارهٔ فروشگاه'],['/contact','ارتباط با فروشگاه'],...(localPath(shop)?[[localPath(shop),'تجهیزات عکاسی در '+shop.city]]:[])];}
function guides(c){return `<div class="guide-grid">${['camera','lenses','rental'].map((p,i)=>`<a class="guide-card" href="/guides/${p}">${field(c,'guide'+(i+1)+'Title','h3')}${field(c,'guide'+(i+1)+'Text','p')}${arrow}</a>`).join('')}</div>`;}
function contacts(c,shop){return `<div class="contact-details"><div><span>موقعیت</span><b>${esc([shop.province,shop.city].filter(Boolean).join('، '))}</b></div>${['phone','address','hours'].map((k,i)=>`<div><span>${['شمارهٔ تماس','نشانی','ساعت پاسخ‌گویی'][i]}</span>${field(c,k,'p','class="empty-field" data-placeholder="کلیک برای تکمیل اطلاعات عمومی"')}</div>`).join('')}</div>`;}
const faqs=c=>c.faqs.map(x=>`<details class="faq-item" data-site-faq="${esc(x.id)}"><summary><span data-collection-field="question" data-site-style="faq:${esc(x.id)}:question">${esc(x.question)}</span><span class="faq-toggle" aria-hidden="true">＋</span></summary><p data-collection-field="answer" data-site-style="faq:${esc(x.id)}:answer">${esc(x.answer)}</p></details>`).join('');
function equipmentSection(shop,c,key){const head=(a,b)=>`<div class="section-heading"><div>${field(c,a,'h2')}${b?field(c,b,'p'):''}</div></div>`,link=(p,key)=>`<a class="text-link" href="${p}">${field(c,key)}${arrow}</a>`;const blocks={services:`<section class="site-section" data-site-section="services">${head('servicesTitle','servicesText')}<div class="service-grid">${c.serviceCards.map(x=>`<article class="service-card" data-site-card="${esc(x.id)}"><div class="service-album" data-service-album><div class="service-card-gallery" tabindex="0" aria-label="تصاویر ${esc(x.title)}">${x.images.map((src,i)=>`<img data-album-slide data-card-image="${i}" ${i?'hidden':''} src="${esc(src)}" width="900" height="600" alt="${esc(x.title)}" loading="lazy">`).join('')}</div></div><div><h3 data-collection-field="title" data-site-style="card:${esc(x.id)}:title">${esc(x.title)}</h3><p data-collection-field="text" data-site-style="card:${esc(x.id)}:text">${esc(x.text)}</p><a class="text-link" href="${esc(x.href)}"><span data-collection-field="button" data-site-style="card:${esc(x.id)}:button">${esc(x.button)}</span></a></div></article>`).join('')}</div></section>`,steps:`<section class="site-section" data-site-section="steps">${head('stepsTitle')}<div class="steps-grid">${[1,2,3].map(i=>`<article>${field(c,'step'+i+'Title','h3')}${field(c,'step'+i+'Text','p')}</article>`).join('')}</div>${link('/order-guide','stepsButton')}</section>`,gallery:`<section class="site-section gallery-section" data-site-section="gallery"><div>${head('galleryTitle','galleryText')}${link('/guides/lenses','galleryButton')}</div>${img(c,'gallery','کیت تجهیزات')}</section>`,guides:`<section class="site-section" data-site-section="guides">${head('guideTitle','guideText')}${guides(c)}</section>`,faq:`<section class="site-section faq-section" data-site-section="faq">${head('faqTitle')}<div>${faqs(c)}${link('/faq','faqButton')}</div></section>`,about:`<section class="site-section about-section" data-site-section="about">${field(c,'aboutTitle','h2')}${field(c,'aboutText','p')}${link('/about','aboutButton')}</section>`,contact:`<section class="site-section contact-section" data-site-section="contact"><div>${head('contactTitle','contactText')}${link('/contact','contactButton')}</div>${contacts(c,shop)}</section>`};return blocks[key]||'';}
function home(shop,c){return `<section class="hero" data-site-section="hero"><div class="hero-copy">${field(c,'heroTitle','h1')}${field(c,'heroText','p')}<div class="actions"><a class="primary" href="/products">${field(c,'heroButton')}${arrow}</a><a class="secondary" href="/guides">${field(c,'secondaryButton')}</a></div><div class="hero-note">${field(c,'heroNote')}</div></div><div class="hero-visual">${img(c,'hero','دوربین و تجهیزات روی میز')}</div></section>`;}
function pageData(path,shop,c,preview=false){const pages={
 '/equipment':['تجهیزات عکاسی و فیلم‌برداری','تجهیزات را بر اساس کاربرد، سازگاری و شرایط استفاده انتخاب کنید.','<h2>از نیاز پروژه شروع کنید</h2><p>نوع سوژه، نور محیط، عکاسی یا فیلم‌برداری و مدت استفاده را مشخص کنید. سپس دوربین، لنز و لوازم جانبی را به‌عنوان یک مجموعه ببینید. گران‌تر بودن یک قطعه به معنی مناسب‌تر بودن آن برای همهٔ پروژه‌ها نیست.</p><h2>سازگاری را پیش از انتخاب بررسی کنید</h2><p>مانت لنز، اندازهٔ حسگر، نوع باتری، اتصالات صدا و تصویر و ظرفیت کارت حافظه را با مدل دقیق دستگاه مقایسه کنید. برای قطعات تخصصی، نام کامل مدل و مشخصات سازنده را بررسی و با فروشگاه هماهنگ کنید.</p><h2>فهرست واقعی کالاها</h2><p>ملاک خرید، کالاهای فعال و موجود در فهرست فروشگاه است.</p>'],
 '/rental-equipment':['اجاره و آفیش تجهیزات عکاسی','برای پروژهٔ مشخص، تجهیزات و تاریخ‌های موردنیاز را از قبل آماده کنید.','<h2>ورود عکاس و تأیید همکاری</h2><p>از بخش آفیش همین سایت با حساب عکاسی فوتوبریج وارد شوید. ثبت درخواست به عضویت و تأیید همکاری با همین فروشگاه وابسته است؛ ورود به حساب، به‌تنهایی تأیید اجاره نیست.</p><h2>تاریخ و موجودی</h2><p>تاریخ شروع و پایان را دقیق مشخص کنید. موجودی و قیمت اجاره در مسیر آفیش بررسی می‌شوند. درخواست تا زمانی که مطابق فرایند فروشگاه تأیید نشده، رزرو قطعی یا تضمین تحویل محسوب نمی‌شود.</p><h2>پیش از تحویل</h2><p>متعلقات، شرایط ودیعه، ساعت تحویل و بازگشت را با فروشگاه هماهنگ کنید. هنگام تحویل، وضعیت ظاهری و کارکرد تجهیزات و فهرست لوازم همراه را بررسی کنید.</p>'],
 '/guides':['راهنمای انتخاب تجهیزات','پیش از خرید یا آفیش، کاربرد و سازگاری را با هم بسنجید.',guides(c)],
 '/guides/camera':['راهنمای انتخاب دوربین عکاسی و فیلم‌برداری','دوربین مناسب، دوربینی است که با نیاز و مجموعهٔ تجهیزات شما هماهنگ باشد.','<h2>کاربرد و نور محیط</h2><p>عکاسی ورزشی، محصول، پرتره و فیلم‌برداری نیاز یکسانی ندارند. فوکوس، شرایط نور، اندازه و وزن بدنه و مدت کار مداوم را بر اساس کاربرد واقعی بسنجید.</p><h2>نیازهای ویدئویی</h2><p>برای فیلم‌برداری، فقط رزولوشن را مقایسه نکنید. نرخ فریم، فرمت ضبط، زمان کار، ورودی صدا و ابزارهای موردنیاز در تدوین مهم‌اند. مشخصات مدل دقیق را از اطلاعات سازنده بررسی کنید.</p><h2>هزینهٔ مجموعهٔ کامل</h2><p>لنز، باتری، کارت حافظه، نور، صدا و ابزار نگهداری بخشی از انتخاب‌اند. پیش از خرید یا اجاره، متعلقات موردنیاز را فهرست و با اقلام همراه کالا مقایسه کنید.</p>'],
 '/guides/lenses':['راهنمای انتخاب لنز و بررسی سازگاری','مانت، اندازهٔ حسگر و فاصلهٔ کانونی را پیش از انتخاب لنز بشناسید.','<h2>مانت و حسگر</h2><p>نام برند به‌تنهایی برای تشخیص سازگاری کافی نیست. مانت دقیق و سازگاری لنز با حسگر و بدنه را بررسی کنید. استفاده از تبدیل ممکن است محدودیت‌هایی در فوکوس یا عملکرد ایجاد کند؛ آن را برای ترکیب دقیق تجهیزات خود بسنجید.</p><h2>فاصلهٔ کانونی</h2><p>فاصلهٔ کانونی بر زاویهٔ دید اثر دارد. لنز واید، استاندارد و تله کاربردهای متفاوتی دارند. فاصلهٔ شما تا سوژه، فضای کار و نوع تصویر موردنظر را در انتخاب لحاظ کنید.</p><h2>دیافراگم و لرزش‌گیر</h2><p>دیافراگم بازتر می‌تواند در نور کم و کنترل عمق میدان کمک کند، اما تنها معیار کیفیت یا تناسب لنز نیست. وزن، حداقل فاصلهٔ فوکوس، لرزش‌گیر و عملکرد روی بدنهٔ شما هم مهم‌اند.</p>'],
 '/guides/rental':['چک‌لیست آماده‌سازی آفیش تجهیزات','تاریخ‌ها و لوازم موردنیاز را پیش از ثبت درخواست روشن کنید.','<h2>پیش از ثبت درخواست</h2><ul><li>تاریخ و مدت استفاده و نام دقیق تجهیزات را مشخص کنید.</li><li>بدنه، لنز و لوازم جانبی را از نظر سازگاری بررسی کنید.</li><li>شرایط همکاری، ودیعه و تحویل را از فروشگاه بپرسید.</li></ul><h2>هنگام تحویل و بازگشت</h2><p>فهرست متعلقات و وضعیت ظاهری و عملکرد را بررسی کنید. شرایط حمل، نگهداری و زمان بازگشت را رعایت کنید. برای تمدید یا تغییر درخواست، پیش از پایان زمان توافق‌شده با فروشگاه هماهنگ کنید.</p><p>این راهنما به معنی فعال‌بودن اجاره برای همهٔ کالاها نیست. مسیر آفیش فقط در فروشگاه دارای اجاره و مطابق دسترسی حساب عکاس ارائه می‌شود.</p>'],
 '/order-guide':['راهنمای خرید و آفیش تجهیزات','خرید عمومی و اجارهٔ عکاسان از دو مسیر مشخص انجام می‌شوند.','<h2>خرید عمومی</h2><p>اگر فروش فعال باشد، کالا و تعداد را انتخاب و به سبد اضافه کنید. مشخصات تماس و روش تحویل را وارد کنید. پس از ثبت سفارش، اطلاعات واریز فروشگاه نمایش داده می‌شود؛ رسید پرداخت را ارسال و شماره و لینک پیگیری را نگه دارید. تأیید رسید توسط فروشگاه انجام می‌شود.</p><h2>آفیش عکاسان</h2><p>اگر اجاره فعال باشد، با حساب عکاس وارد شوید. همکاری تأییدشده، تاریخ‌ها، موجودی و شرایط فروشگاه در ثبت درخواست نقش دارند. خرید عمومی جایگزین تأیید همکاری یا رزرو تجهیزات نیست.</p><h2>هماهنگی تحویل</h2><p>زمان آماده‌سازی، متعلقات، شرایط دریافت و ارسال را با فروشگاه هماهنگ کنید. نشانی یا ساعت درج‌نشده را از خود فروشگاه دریافت کنید.</p>'],
 '/faq':['پرسش‌های متداول فروشگاه تجهیزات','پاسخ پرسش‌های خرید، موجودی و آفیش.','<div data-equipment-faq-list>'+faqs(c)+'</div>'],
 '/about':['دربارهٔ '+c.displayName,c.aboutText,'<h2>خدمات فروشگاه</h2><p>فروش و اجاره بر اساس امکانات فعال همین فروشگاه ارائه می‌شوند. مشخصات و موجودی هر کالا را در فهرست واقعی آن بررسی کنید.</p>'+contacts(c,shop)],
 '/reviews':['نظر کاربران','تجربه و امتیاز کاربران فروشگاه',preview?reviewsMarkup.replace('<form ', '<form inert '):reviewsMarkup],
 '/contact':['ارتباط با '+c.displayName,c.contactText,contacts(c,shop)+'<h2>برای هماهنگی چه اطلاعاتی داشته باشم؟</h2><p>نام کامل کالا، مدل، کاربرد موردنظر و در صورت ثبت سفارش، شمارهٔ آن را آماده داشته باشید. برای آفیش، تاریخ شروع و پایان و فهرست متعلقات هم مهم‌اند.</p>']};if(localPath(shop))pages[localPath(shop)]=['تجهیزات عکاسی در '+shop.city,'مشاهدهٔ تجهیزات و هماهنگی سفارش با '+c.displayName+' در '+shop.city+'.','<h2>انتخاب و هماهنگی پیش از مراجعه</h2><p>کالاهای فعال را در سایت ببینید و برای بررسی سازگاری، موجودی و تحویل با فروشگاه هماهنگ کنید. خدمات فروش یا اجاره به تنظیمات و شرایط همین فروشگاه وابسته‌اند.</p>'+contacts(c,shop)];if(path==='/rental-equipment'&&!shop.rental_enabled)return null;return pages[path];}
export function renderEquipmentPage(shop,saved,origin,{pathname='/',hostname='shop.example.com',nonce='',preview=false,catalog=''}={}){const c=mergeEquipmentSite(shop,saved),doc=pageData(pathname,shop,c,preview),missing=pathname!=='/'&&pathname!=='/products'&&!doc,title=pathname==='/'?(c.metaTitle||'فروشگاه تجهیزات عکاسی و فیلم‌برداری | '+c.displayName):missing?'صفحه پیدا نشد':pathname==='/products'?'محصولات فروشگاه':doc[0]+' | '+c.displayName,description=pathname==='/'?(c.metaDescription||c.heroText):doc?.[1]||(pathname==='/products'?'مشاهدهٔ کالاها و قیمت فروشگاه':'صفحه پیدا نشد.'),site='https://'+hostname;
const productHeading=`<section class="equipment-products-heading"><h1 data-site-style="page:/products:title">محصولات ${esc(c.displayName)}</h1></section>`;const body=(pathname==='/products'||pathname==='/rental-equipment'&&catalog)?catalog.replace('<!--EQUIPMENT_PRODUCTS_HEADING-->',pathname==='/rental-equipment'?'<h1 id="rentalTitle" class="site-visually-hidden">ورود به آفیش تجهیزات</h1>':productHeading):pathname==='/'?home(shop,c):missing?'<section class="page-hero"><h1>این صفحه پیدا نشد.</h1><a href="/">بازگشت به خانه</a></section>':`<nav class="breadcrumbs" aria-label="مسیر صفحه"><a href="/">خانه</a><span>/</span><span>${esc(doc[0])}</span></nav><section class="page-hero"><h1 data-site-style="page:${esc(pathname)}:title">${esc(doc[0])}</h1><p data-site-style="page:${esc(pathname)}:description">${esc(doc[1])}</p></section><div class="article-layout"><article class="article-body">${pathname==='/equipment'?equipmentSection(shop,c,'services')+equipmentSection(shop,c,'gallery'):pathname==='/order-guide'?equipmentSection(shop,c,'steps')+doc[2]:pathname==='/about'?field(c,'aboutText','p')+contacts(c,shop):doc[2]}</article></div>`;
const schema=JSON.stringify([{'@context':'https://schema.org','@type':'WebSite',name:c.displayName,url:site+'/',inLanguage:'fa-IR'},{'@context':'https://schema.org','@type':'Organization',name:c.displayName,url:site+'/',...(c.phone?{telephone:c.phone}:{})},...(pathname==='/'||missing?[]:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'خانه',item:site+'/'},{'@type':'ListItem',position:2,name:doc?.[0]||'محصولات فروشگاه',item:site+pathname}]}])]).replace(/</g,'\\u003c');
const activePath=pathname.startsWith('/guides')?'/guides':pathname;const markNavigation=html=>html.replace(/<nav class="(?:desktop-nav|mobile-menu-links)"[^>]*>[\s\S]*?<\/nav>/g,nav=>nav.replace(/<a href="([^"]+)"/g,(tag,href)=>tag+(href===activePath?' aria-current="page"':'')));return {status:missing?404:200,html:withSiteLayout(styleSiteText(markNavigation(`<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="${preview||missing?'noindex,nofollow':'index,follow'}"><link rel="canonical" href="${esc(site+pathname)}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${esc(site+pathname)}"><meta property="og:image" content="${site}/equipment-site/studio-camera.webp"><link rel="stylesheet" href="/lab-storefront.css?v=r1276">${catalog?'<link rel="stylesheet" href="/storefront.css?v=r1272"><script defer src="/storefront-rental.js?v=r1273"></script><script defer src="/storefront.js?v=r1273"></script>':''}<link rel="stylesheet" href="/equipment-site.css?v=r1277"><script defer src="/equipment-album.js?v=r1273"></script>${!preview&&pathname==='/reviews'?'<script defer src="/site-reviews.js?v=r1276"></script>':''}${preview?'':'<script defer src="/equipment-site.js?v=r1277"></script>'}<style nonce="${esc(nonce)}">:root{--primary:${c.primary};--page-bg:${c.background};--ink:${c.ink};--site-font:${c.font};--site-size:${c.fontSize}px;--site-scale:${c.fontSize/15}}</style><script nonce="${esc(nonce)}" type="application/ld+json">${schema}</script></head><body class="equipment-site" data-equipment-site="true" data-equipment-page="${esc(pathname)}"><a class="skip-link" href="#main">رفتن به محتوا</a><header class="site-header"><div class="header-inner"><a class="brand" href="/"><img class="equipment-logo" data-site-image="logo" src="${esc(c.images.logo)}" width="40" height="40" alt="نشان ${esc(c.displayName)}">${field(c,'displayName')}</a><nav class="desktop-nav" aria-label="منوی اصلی"><a href="/">خانه</a><a href="/equipment">${field(c,'navServices')}</a><a href="/products">${field(c,'navPrices')}</a><a href="/guides">${field(c,'navGuides')}</a><a href="/about">${field(c,'navAbout')}</a><a href="/faq">پرسش‌های متداول</a><a href="/contact">ارتباط</a><a href="/reviews">نظر کاربران</a></nav>${shop.rental_enabled?`<details class="photographer-dropdown"><summary class="header-login"><svg class="login-user-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="8" r="3.5" stroke="currentColor" stroke-width="1.6"/><path d="M5 21v-2a7 7 0 0 1 14 0v2" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>${field(c,'navPhotographers')}</summary><div class="photographer-panel"><div class="login-panel-heading"><h2>حساب عکاس</h2><button type="button" class="login-panel-close" aria-label="بستن ورود عکاسان">×</button></div><form id="equipmentHeaderLogin" ${preview?'inert':''}><label>شماره موبایل<input name="mobile" type="tel" inputmode="tel" autocomplete="username" dir="ltr" required></label><label>رمز عبور<input name="password" type="password" autocomplete="current-password" required></label><button type="submit" class="primary">ورود</button></form><div id="equipmentHeaderSession" hidden><p>حساب عکاس: <b></b></p><a class="primary" href="/rental-equipment">مشاهدهٔ آفیش تجهیزات</a><button type="button" id="equipmentHeaderLogout">خروج از حساب</button></div><p id="equipmentHeaderMessage" role="status" aria-live="polite"></p></div></details>`:`<a class="header-login" href="/products">${field(c,'navPhotographers')}</a>`}<details class="mobile-menu"><summary aria-label="باز کردن منوی سایت">☰</summary><nav class="mobile-menu-links"><a href="/">خانه</a><a href="/equipment">خدمات تجهیزات</a><a href="/products">محصولات و آفیش</a><a href="/guides">راهنماها</a><a href="/about">دربارهٔ ما</a><a href="/faq">پرسش‌های متداول</a><a href="/contact">ارتباط</a><a href="/reviews">نظر کاربران</a></nav></details></div></header><main id="main" class="site-main">${body}</main><footer class="site-footer"><div class="footer-grid"><div class="footer-brand">${field(c,'displayName','b')}${field(c,'footerText','p')}<div class="footer-icon-slots" aria-hidden="true">${[1,2,3,4].map(i=>'<span data-footer-icon-slot="'+i+'"></span>').join('')}</div></div><nav aria-label="خدمات فروشگاه"><b class="footer-label">خدمات فروشگاه</b><a href="/equipment">تجهیزات عکاسی و فیلم‌برداری</a><a href="/products">محصولات فروشگاه</a><a href="/order-guide">راهنمای خرید و آفیش</a></nav><nav aria-label="همراه شما"><b class="footer-label">همراه شما</b><a href="/faq">پرسش‌های متداول</a><a href="/about">دربارهٔ ما</a><a href="/contact">ارتباط</a><a href="/reviews">نظر کاربران</a>${localPath(shop)?`<a href="${localPath(shop)}">تجهیزات عکاسی در ${esc(shop.city)}</a>`:''}</nav></div><div class="equipment-footer-bottom"><span>این سایت متعلق به <a href="https://photobridge.ir" rel="noopener">فوتوبریج</a> است.</span><span class="footer-wordmark" lang="en" dir="ltr">PhotoBridge</span></div></footer></body></html>`),c.textStyles,pathname),c.layout,pathname,nonce)};}
